class Solution:
    def queue(self, operations: list[list], lease: float) -> list:
        items=[]
        result=[]
        for op in operations:
            if op[0]=="enqueue":items.append([op[1],float(op[2])])
            elif op[0]=="ack":items=[item for item in items if item[0]!=op[1]]
            else:
                now=op[1]
                available=next((item for item in items if item[1]<=now),None)
                result.append(available[0] if available else None)
                if available:available[1]=now+lease
        return result

